// 1. 命令侧：围绕聚合处理写入，并在同一事务内记录待发布事件
public class CreateOrderCommandHandler {
    private final OrderRepository orderRepository;
    private final OutboxRepository outboxRepository;

    @Transactional
    public OrderId handle(CreateOrderCommand cmd) {
        Order order = Order.create(cmd.getCustomerId(), cmd.getItems(), cmd.getRequestId());
        orderRepository.save(order);
        outboxRepository.append(order.pullDomainEvents());
        return order.getId();
    }
}

// 2. 查询侧：只读物化视图，不反向修改写模型
public class OrderQueryService {
    private final OrderReadRepository readRepo;

    public OrderSummaryDTO getOrderSummary(OrderId orderId) {
        return readRepo.findById(orderId);
    }

    public List<OrderListItemDTO> searchOrders(OrderQuery query) {
        return readRepo.search(query);
    }
}

// 3. 投影器：事件处理必须幂等，重复投递不应重复累计金额或订单数
public class OrderReadModelProjector {
    private final OrderReadRepository readRepo;

    public void on(OrderCreatedEvent event) {
        if (readRepo.hasApplied(event.getEventId())) {
            return;
        }
        OrderReadModel readModel = new OrderReadModel();
        readModel.setOrderId(event.getOrderId());
        readModel.setCustomerId(event.getCustomerId());
        readModel.setTotalAmount(event.getTotalAmount());
        readModel.setCreatedAt(event.getCreatedAt());
        readRepo.save(readModel, event.getEventId());
    }
}

// 4. Event Sourcing：通过事件流恢复聚合，通过版本号避免并发覆盖
public class OrderAggregate {
    private OrderId id;
    private OrderStatus status;
    private Money totalAmount;
    private long version;
    private final List<DomainEvent> pendingEvents = new ArrayList<>();

    public static OrderAggregate rehydrate(List<DomainEvent> history) {
        OrderAggregate order = new OrderAggregate();
        for (DomainEvent event : history) {
            order.apply(event);
            order.version = event.getVersion();
        }
        return order;
    }

    public void confirm() {
        if (this.status != OrderStatus.CREATED) {
            throw new DomainException("订单状态不允许确认");
        }
        registerEvent(new OrderConfirmedEvent(this.id, this.version + 1));
    }

    private void registerEvent(DomainEvent event) {
        apply(event);
        pendingEvents.add(event);
    }

    private void apply(DomainEvent event) {
        if (event instanceof OrderCreatedEvent created) {
            this.id = created.getOrderId();
            this.status = OrderStatus.CREATED;
            this.totalAmount = created.getTotalAmount();
        }
        if (event instanceof OrderConfirmedEvent) {
            this.status = OrderStatus.CONFIRMED;
        }
    }
}
